import{_ as o,o as t,c as d,a2 as c}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"CLI 命令","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/cli/overview.md","filePath":"zh-CN/cli/overview.md","lastUpdated":1784903584000}'),r={name:"zh-CN/cli/overview.md"};function a(l,e,i,n,s,h){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="cli-命令" tabindex="-1">CLI 命令 <a class="header-anchor" href="#cli-命令" aria-label="Permalink to &quot;CLI 命令&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><code>swag2mcp</code> CLI 是所有操作的单一入口点 — 从初始化工作区和管理 API 规范到启动用于 LLM 集成的 MCP 服务器。它提供 <strong>13 个命令</strong>，涵盖使用 OpenAPI/Swagger/Postman 规范的完整生命周期。</p><h3 id="cli-解决的问题" tabindex="-1">CLI 解决的问题 <a class="header-anchor" href="#cli-解决的问题" aria-label="Permalink to &quot;CLI 解决的问题&quot;">​</a></h3><ul><li><strong>工作区生命周期</strong> — 创建（<code>init</code>）、检查（<code>info</code>、<code>ls</code>）、清理（<code>clean</code>）、更新（<code>update</code>）和删除（<code>delete</code>）工作区及其内容</li><li><strong>Spec 和 collection 管理</strong> — 添加（<code>add</code>）、列出（<code>ls</code>）和删除（<code>delete</code>）API 规范及其 collection</li><li><strong>运行模式</strong> — 启动 MCP 服务器以进行 LLM 工具访问（<code>mcp</code>）或启动交互式 TUI 浏览器（<code>run</code>）</li><li><strong>诊断</strong> — 验证配置（<code>validate</code>）、显示版本（<code>version</code>）、显示运行时信息（<code>info</code>）</li><li><strong>备份和恢复</strong> — 通过 ZIP 进行完整工作区往返（<code>export</code>、<code>import</code>）</li></ul><h3 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h3><ul><li><strong>路径解析</strong> — 接受 <code>[path]</code> 的命令期望的是<strong>工作区目录</strong>（不是文件路径）。解析顺序：显式 <code>[path]</code> → 当前目录（<code>./</code>）→ <code>~/.swag2mcp/</code>。CLI 自动追加 <code>swag2mcp.yaml</code>。作为服务运行或在 IDE 配置中时，始终传递显式路径，以避免加载错误的工作区。</li><li><strong>Spec vs Collection</strong> — <strong>spec</strong> 代表逻辑 API 服务（例如&quot;Open-Meteo API&quot;），而 <strong>collection</strong> 是一个 OpenAPI/Swagger/Postman 文件。一个 spec 可以有多个 collection。</li><li><strong><code>--version</code></strong> 既支持作为标志（<code>swag2mcp --version</code>），也支持作为子命令（<code>swag2mcp version</code>）。</li><li><strong><code>add spec</code> / <code>add collection</code></strong> 通过 <code>--yaml</code>（内联字符串或 <code>-</code> 表示 stdin）接受 YAML 输入。从文件或 heredoc 管道输入可以避免特殊字符的 shell 引号问题。</li><li><strong><code>delete</code></strong> 需要 TTY（交互式终端）。没有 <code>--force</code> 或 <code>--yes</code> 标志 — 它始终提示选择和确认。</li><li><strong><code>mcp</code></strong> 是 LLM 集成的主要命令。它支持三种传输方式：<code>stdio</code>（默认）、<code>sse</code> 和 <code>streamable-http</code>。<code>--disable-llm-auth</code> 标志（默认：<code>true</code>）从 MCP 工具列表中移除 <code>auth</code> 工具，防止 LLM 看到或请求令牌。认证仍然有效 — 令牌通过标准配置机制获取，而不是通过 LLM。此模式推荐用于<strong>生产环境</strong>（LLM 永远无法访问凭据）。对于<strong>调试</strong>或使用短期令牌时，设置 <code>--disable-llm-auth=false</code> 让 LLM 通过 <code>auth</code> 工具请求新令牌。</li><li><strong><code>validate</code></strong> 检查 YAML 语法、配置结构、规范文件存在性、URL 可达性、规范格式（OpenAPI/Swagger/Postman）、认证设置和 HTTP 客户端正确性。它<strong>不</strong>测试认证端点或 API 端点可用性。</li><li><strong><code>export</code> / <code>import</code></strong> 提供完整的工作区往返 — 配置文件、规范文件、缓存和认证脚本都包含在 ZIP 归档中。</li><li><strong><code>clean</code></strong> 删除 <code>cache/</code> 和 <code>responses/</code> 目录，但保留 <code>specs/</code> 和 <code>auth_scripts/</code>。旧响应（超过 48 小时）也会在 <code>mcp</code> 启动时自动清理。</li></ul><h2 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>描述</th></tr></thead><tbody><tr><td><a href="/cli/init"><code>init</code></a></td><td>使用默认配置初始化工作区目录</td></tr><tr><td><a href="/cli/add"><code>add</code></a></td><td>向配置添加 spec 或 collection</td></tr><tr><td><a href="/cli/delete"><code>delete</code></a></td><td>交互式删除 spec 或 collection</td></tr><tr><td><a href="/cli/ls"><code>ls</code></a></td><td>列出所有 spec 及其 collection</td></tr><tr><td><a href="/cli/run"><code>run</code></a></td><td>启动交互式 TUI API 浏览器</td></tr><tr><td><a href="/cli/validate"><code>validate</code></a></td><td>验证配置和规范文件</td></tr><tr><td><a href="/cli/clean"><code>clean</code></a></td><td>清除缓存的规范和调用响应</td></tr><tr><td><a href="/cli/update"><code>update</code></a></td><td>重新验证、重新缓存和重新索引所有 spec</td></tr><tr><td><a href="/cli/mcp"><code>mcp</code></a></td><td>启动 MCP 服务器以进行 LLM 工具访问</td></tr><tr><td><a href="/cli/version"><code>version</code></a></td><td>打印 swag2mcp 版本</td></tr><tr><td><a href="/cli/info"><code>info</code></a></td><td>显示详细的配置和运行时信息</td></tr><tr><td><a href="/cli/import"><code>import</code></a></td><td>导入规范文件或从 ZIP 恢复工作区</td></tr><tr><td><a href="/cli/export"><code>export</code></a></td><td>将工作区导出为可移植的 ZIP 备份</td></tr></tbody></table><h2 id="全局标志" tabindex="-1">全局标志 <a class="header-anchor" href="#全局标志" aria-label="Permalink to &quot;全局标志&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标志</th><th>描述</th></tr></thead><tbody><tr><td><code>--version</code></td><td>显示版本（与 <code>version</code> 子命令相同）</td></tr><tr><td><code>--help</code></td><td>显示任何命令的帮助信息</td></tr></tbody></table>',11)])])}const m=o(r,[["render",a]]);export{g as __pageData,m as default};
